// Contoh tanpa hardware: dua register float32 (urutan biasa) bernilai 12345.5 kWh. Pastikan meter MTR-LINE1 sudah didaftarkan.
const b = Buffer.alloc(4); b.writeFloatBE(12345.5, 0);
return { meter: 'MTR-LINE1', format: 'f32', scale: 1, payload: [b.readUInt16BE(0), b.readUInt16BE(2)] };

// Daftar meter yang dibaca. Ubah sesuai pabrik Anda, lalu sambungkan keluaran node ini ke node "Modbus Flex Getter"
// (pasang palet node-red-contrib-modbus, atur koneksinya ke gateway RS-485/Modbus TCP), dan keluaran Modbus ke "Decode & kirim".
// meter  = kode yang didaftarkan di MaintHub (Electrical & Utility -> Pengaturan -> Power meter)
// unitid = alamat slave Modbus; address = alamat register energi kumulatif (LIHAT MANUAL meter Anda), quantity = jumlah register
// format = f32 | f32sw | u32 | u32sw | u16  (urutan word; coba f32sw bila angka aneh)   scale = pengali ke kWh (mis. 0.001 bila register dalam Wh)
const METERS = [
  { meter: 'MTR-LINE1', unitid: 1, address: 342, quantity: 2, fc: 3, format: 'f32', scale: 1 },
  { meter: 'MTR-BOILER', unitid: 2, address: 342, quantity: 2, fc: 3, format: 'f32', scale: 1 },
];
return [METERS.map((m) => ({ meter: m.meter, format: m.format, scale: m.scale, payload: { fc: m.fc, unitid: m.unitid, address: m.address, quantity: m.quantity } }))];

// Masukan: msg.payload = array register 16-bit hasil baca Modbus, msg.meter = kode meter, msg.format dan msg.scale (lihat node "Daftar meter").
const base = (env.get('MAINTHUB_URL') || '').replace(/\/+$/, '');
const key = env.get('MAINTHUB_KEY');
const bad = (t) => { node.warn(t); node.status({ fill: 'red', shape: 'ring', text: t.slice(0, 40) }); return [null, { payload: t }]; };
if (!base || !key) return bad('isi MAINTHUB_URL dan MAINTHUB_KEY di tab ini');
const r = msg.payload;
if (!Array.isArray(r) || !r.length || !r.every((x) => Number.isInteger(x) && x >= 0 && x <= 0xFFFF)) return bad('register tidak valid untuk ' + msg.meter);
if (!msg.meter) return bad('msg.meter kosong');
const fmt = msg.format || 'f32'; const scale = Number(msg.scale === undefined ? 1 : msg.scale);
let v;
if (fmt === 'u16') v = r[0];
else if (r.length < 2) return bad('format ' + fmt + ' butuh 2 register');
else {
  const swap = fmt.endsWith('sw'); const hi = swap ? r[1] : r[0]; const lo = swap ? r[0] : r[1];
  const b = Buffer.alloc(4); b.writeUInt16BE(hi, 0); b.writeUInt16BE(lo, 2);
  v = fmt.startsWith('f32') ? b.readFloatBE(0) : b.readUInt32BE(0);
}
v = v * scale;
if (!Number.isFinite(v) || v < 0) return bad('nilai tidak masuk akal (' + v + ') untuk ' + msg.meter + ': cek format/alamat register');
node.status({ fill: 'green', shape: 'dot', text: msg.meter + ' ' + v.toFixed(2) + ' kWh' });
return [{ url: base + '/api/ingest/meters', method: 'POST', headers: { 'x-api-key': key, 'content-type': 'application/json' }, payload: { meters: [{ meter: msg.meter, kwh: Number(v.toFixed(3)) }] } }, null];

const ok = msg.statusCode === 200 && msg.payload && !(msg.payload.errors && msg.payload.errors.length);
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'diterima ' + msg.payload.accepted + ' (hari dihitung: ' + msg.payload.daysUpdated + ')' : 'GAGAL ' + msg.statusCode });
if (!ok) node.warn('MaintHub: ' + msg.statusCode + ' ' + JSON.stringify(msg.payload).slice(0, 300));
return msg;
